28	  test('archiving drops a project off the main list, keeps a record, and loses nothing', async ({ page }) => {
29	    await resetAndSeed({
30	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
31	      projects: [
32	        { id: 1, clientId: 1, name: 'Website redesign' },
33	        { id: 2, clientId: 1, name: 'Warehouse automation' },
34	      ],
35	    });
36	
37	    await page.goto('/projects');
38	    await expect(page.getByTestId('projects-page')).toBeVisible();
39	
40	    const first = page.getByTestId('project-row-1');
41	    const second = page.getByTestId('project-row-2');
42	    await expect(first).toBeVisible();
43	    await expect(second).toBeVisible();
44	
45	    // reset cleared the audit file — nothing has been archived yet.
46	    expect(auditLines()).toEqual([]);
47	
48	    // Tuck the first project away.
49	    await page.getByTestId('project-archive-1').click();
50	
51	    // It drops off the default list; its sibling is untouched.
52	    await expect(first).toHaveCount(0);
53	    await expect(second).toBeVisible();
54	    await expect(second.getByTestId('project-name')).toHaveText('Warehouse automation');
55	
56	    // Exactly one record was kept, naming the archived project — and only that one (not DELETED).
57	    await expect.poll(() => auditLines()).toEqual(['PROJECT_ARCHIVED id=1']);
58	
59	    // Nothing was lost: revealing archived projects brings it back, name intact.
60	    await page.getByTestId('projects-show-archived').click();
