1	// Acceptance tests for the change request:
2	//   "Work out for me whether an invoice is paid, part paid or still owing. Base it on the payments
3	//    I have recorded. I do not want to flip it to paid by hand anymore."
4	//
5	// An invoice's payment status is now WORKED OUT from the payments recorded against it, not set by
6	// hand. On the invoice's own detail page (invoice-detail-page, at /invoices/<id> — the same public
7	// URL surface the invoice specs already use, and the one place that shows that invoice's payments)
8	// a status panel (invoice-status-panel) states which of the three it is:
9	//   - nothing paid yet                     -> still owing
10	//   - some paid, but less than the amount  -> part paid
11	//   - payments cover the whole amount      -> paid
12	// Because it is derived "from the payments I have recorded", it is scoped to the ONE invoice: each
13	// invoice's status is worked out from its OWN payments, never a sibling's. Recording a payment keeps
14	// one audit record — PAYMENT_RECORDED id=<id> amount=<amount> — so what the status was worked out
15	// from can be checked back later.
16	//
17	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
18	// (auditLines()). Data is arranged via resetAndSeed, which honours invoices: { id, projectId, amount,
19	// status } and payments: { id, invoiceId, amount, date } (alongside clients / projects); the record-
20	// a-payment flow is driven through the existing payment-form.
21	//
22	// The three states are the change request's own words ("paid", "part paid", "still owing"), asserted
23	// VOCABULARY- and CASING-tolerantly so whichever wording/casing the feature renders passes:
24	//   - "still owing" is matched as /owing|owed|outstanding|unpaid/i,
25	//   - "part paid"   as /part/i (the only state that carries the word "part"),
26	//   - "paid"        as containing /paid/i while NOT carrying /part/i (so a full "paid" is told apart
27	//     from a "part paid").
28	// Each assertion uses only the token that distinguishes its state — never the absence of a money word
29	// that a panel might legitimately show (e.g. a "$0.00 paid" sub-figure) — so a correct panel passes
30	// however richly it is laid out, while a mis-derived status (a leaked sibling payment, a wrong sum)
31	// fails. The audit amount is matched with an optional trailing ".00" so a plain or two-decimal
32	// rendering both pass. This SHOULD FAIL before the change: there is no invoice-status-panel today, and
33	// recording a payment keeps no PAYMENT_RECORDED record.
34	import { test, expect } from '@playwright/test';
35	import { resetAndSeed } from '../support/seed';
36	import { auditLines } from '../support/audit';
37	
38	// The distinguishing token for each worked-out state. Kept deliberately loose on wording but exact on
39	// which state each denotes (see the header note on why "paid" needs the /part/ guard).
40	const OWING = /owing|owed|outstanding|unpaid/i;
41	const PART = /part/i;
42	const PAID = /paid/i;
43	
44	test.describe('an invoice is worked out as paid / part paid / still owing from its payments', () => {
45	  test('works out each invoice from the payments recorded against it', async ({ page }) => {
46	    await resetAndSeed({
47	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
48	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
49	      invoices: [
50	        // Nothing paid against it -> still owing.
51	        { id: 1, projectId: 1, amount: 500, status: 'SENT' },
52	        // 200 of 500 paid -> part paid (worked out, not fully paid).
53	        { id: 2, projectId: 1, amount: 500, status: 'SENT' },
54	        // 100 + 200 = 300 covers the whole 300 -> paid.
55	        { id: 3, projectId: 1, amount: 300, status: 'SENT' },
56	      ],
57	      payments: [
58	        { id: 1, invoiceId: 2, amount: 200, date: '2025-06-15' },
59	        { id: 2, invoiceId: 3, amount: 100, date: '2025-07-11' },
60	        { id: 3, invoiceId: 3, amount: 200, date: '2025-08-20' },
61	      ],
62	    });
63	
64	    // Invoice 1: nothing recorded against it -> still owing. Not part paid: no sibling's payment
65	    // leaked in (if invoice 2's 200 had, it would read as part paid instead).
66	    await page.goto('/invoices/1');
67	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
68	    const panel1 = page.getByTestId('invoice-status-panel');
69	    await expect(panel1).toBeVisible();
70	    await expect(panel1).toContainText(OWING);
71	    await expect(panel1).not.toContainText(PART);
72	
73	    // Invoice 2: 200 of 500 recorded against IT -> part paid. Neither still owing nor fully paid.
74	    await page.goto('/invoices/2');
75	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
76	    const panel2 = page.getByTestId('invoice-status-panel');
77	    await expect(panel2).toBeVisible();
78	    await expect(panel2).toContainText(PART);
79	
80	    // Invoice 3: 100 + 200 = 300 covers its full 300 -> paid, and not merely part paid.
