{
  "//": "Playwright project for the harness. The harness copies authored cpNN specs into e2e/specs/",
  "//specs": "(config.yaml -> acceptance.dest_subpath). Specs bind to data-testid and assert via the UI only.",
  "name": "officehq-e2e",
  "private": true,
  "scripts": {
    "test": "playwright test"
  },
  "devDependencies": {
    "@playwright/test": "1.48.2"
  }
}

